import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";

/** Generated by scripts/gen-world-map.mjs. */
export interface WorldMapData {
  width: number;
  height: number;
  countries: { code: string; name: string; d: string; center: [number, number] }[];
  points: { code: string; center: [number, number] }[];
}

let cached: Promise<WorldMapData> | undefined;
/** The path data is ~45 KB gzipped, so it loads only when a map is shown. */
export function loadWorldMap(): Promise<WorldMapData> {
  cached ??= import("./world-map-data.json").then((module) => (module.default ?? module) as unknown as WorldMapData);
  return cached;
}

const STEPS = 5;

/**
 * Log scale between the smallest and largest non-zero values: a few busy
 * countries must not wash out the rest, and close values must still differ.
 */
export function colorStep(value: number, max: number, min = 1): number {
  if (value <= 0 || max <= 0) return -1;
  if (value >= max) return STEPS - 1;
  const low = Math.log(Math.max(1, min)), high = Math.log(max);
  if (high <= low) return STEPS - 1;
  const step = Math.floor(((Math.log(Math.max(1, value)) - low) / (high - low)) * STEPS);
  return Math.min(STEPS - 1, Math.max(0, step));
}

const stepFill = (step: number) => step < 0
  ? "var(--surface-muted)"
  : `color-mix(in oklab, var(--chart-download) ${[22, 38, 55, 75, 95][step]}%, var(--surface))`;

export function WorldMap({ values, label, onSelect, tooltip, minLabel, maxLabel }: {
  values: Record<string, number>;
  /** Accessible summary; the ranked list next to the map is the readable equivalent. */
  label: string;
  onSelect?: (code: string) => void;
  tooltip: (code: string, name: string | undefined) => ReactNode;
  minLabel?: ReactNode;
  maxLabel?: ReactNode;
}) {
  const [data, setData] = useState<WorldMapData>();
  const [failed, setFailed] = useState(false);
  const [hover, setHover] = useState<{ code: string; name?: string; x: number; y: number; width: number }>();
  const frame = useRef<HTMLDivElement>(null);

  useEffect(() => {
    let alive = true;
    loadWorldMap().then((value) => alive && setData(value), () => alive && setFailed(true));
    return () => { alive = false; };
  }, []);

  const [min, max] = useMemo(() => {
    const present = Object.values(values).filter((value) => value > 0);
    return [Math.min(...present, Infinity), Math.max(0, ...present)];
  }, [values]);
  const shaped = useMemo(() => new Set(data?.countries.map((c) => c.code)), [data]);

  const move = (event: React.PointerEvent, code: string, name?: string) => {
    const rect = frame.current?.getBoundingClientRect();
    if (!rect) return;
    setHover({ code, name, x: event.clientX - rect.left, y: event.clientY - rect.top, width: rect.width });
  };

  if (failed) return null;
  if (!data) return <div className="aspect-[1000/440] w-full animate-pulse rounded-ui-sm bg-ui-surface-muted" aria-hidden="true" />;

  const interactive = (code: string) => Boolean(code && values[code] && onSelect);
  // Small places that carry data but have no 1:110m shape, plus any code the
  // map does not know (drawn nowhere, but still listed beside the map).
  const dots = data.points.filter((point) => !shaped.has(point.code) && values[point.code] > 0);

  return <div ref={frame} className="relative min-w-0" onPointerLeave={() => setHover(undefined)}>
    <svg viewBox={`0 0 ${data.width} ${data.height}`} className="block h-auto w-full" role="img" aria-label={label}>
      <g strokeWidth={0.6} stroke="var(--surface)" strokeLinejoin="round">
        {data.countries.map((country, index) => {
          const value = values[country.code] ?? 0;
          const active = interactive(country.code);
          return <path key={`${country.code}:${index}`} d={country.d}
            fill={stepFill(colorStep(value, max, min))}
            className={active ? "cursor-pointer transition-opacity hover:opacity-80" : undefined}
            data-code={country.code || undefined}
            onPointerMove={(event) => country.code && move(event, country.code, country.name)}
            onClick={active ? () => onSelect!(country.code) : undefined} />;
        })}
      </g>
      <g stroke="var(--surface)" strokeWidth={1}>
        {dots.map((point) => <circle key={point.code} cx={point.center[0]} cy={point.center[1]} r={4.5}
          fill={stepFill(colorStep(values[point.code], max, min))} data-code={point.code}
          className={onSelect ? "cursor-pointer" : undefined}
          onPointerMove={(event) => move(event, point.code)}
          onClick={onSelect ? () => onSelect(point.code) : undefined} />)}
      </g>
    </svg>
    {hover && <div role="tooltip"
      className="pointer-events-none absolute z-10 min-w-40 max-w-64 rounded-ui-sm border border-ui-border bg-ui-surface px-3 py-2 text-xs shadow-ui-card"
      style={{
        left: Math.max(0, Math.min(hover.x + 12, hover.width - 170)),
        top: hover.y + 12,
      }}>
      {tooltip(hover.code, hover.name)}
    </div>}
    <div className="mt-2 flex items-center gap-2 text-xs text-ui-secondary" aria-hidden="true">
      <span>{minLabel}</span>
      <span className="flex overflow-hidden rounded-full">
        {Array.from({ length: STEPS }, (_, step) => <span key={step} className="h-2 w-6" style={{ background: stepFill(step) }} />)}
      </span>
      <span>{maxLabel}</span>
    </div>
  </div>;
}
